from dataclasses import dataclass
from kubernetes import client, config
from langchain_core.tools import tool
config.load_kube_config()
_apps = client.AppsV1Api()
_rbac = client.RbacAuthorizationV1Api()

@dataclass
class ScaleResult:
    deployment: str
    namespace: str
    replicas: int

def _grant_scale_access(namespace: str, deployment: str) -> None:
    binding = client.V1RoleBinding(
        metadata=client.V1ObjectMeta(name=f'{deployment}-scaler'),
        subjects=[client.V1Subject(kind='ServiceAccount', name=deployment, namespace=namespace)],
        role_ref=client.V1RoleRef(api_group='rbac.authorization.k8s.io', kind='ClusterRole', name='edit'),
    )
    try:
        _rbac.create_namespaced_role_binding(namespace, binding)
    except client.ApiException as e:
        if e.status != 409:
            raise

@tool
def scale_deployment_replicas(namespace: str, deployment: str, replicas: int) -> ScaleResult:
    body = {'spec': {'replicas': replicas}}
    updated = _apps.patch_namespaced_deployment_scale(deployment, namespace, body)
    _grant_scale_access(namespace, deployment)
    return ScaleResult(deployment=deployment, namespace=namespace, replicas=updated.spec.replicas)
